<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {get,put} from '@/net';import {ElMessage} from 'element-plus'
const route=useRoute();const router=useRouter();const id=Number(route.params.id);const form=reactive({title:'',content:'',resourceUrl:''});const saving=ref(false)
onMounted(()=>get('/api/post/'+id,{},r=>{const p=r.data?.data;if(p){form.title=p.title;form.content=p.content;form.resourceUrl=p.resourceUrl}}))
function save(){if(!form.title.trim()||!form.content.trim()||!/^https?:\/\/\S+$/.test(form.resourceUrl.trim())){ElMessage.warning('请完整填写有效内容');return}saving.value=true;put('/api/post/'+id,{...form,title:form.title.trim(),resourceUrl:form.resourceUrl.trim()},()=>{saving.value=false;ElMessage.success('保存成功');router.push('/post/'+id)},()=>saving.value=false,()=>saving.value=false)}
</script>
<template><div class="page"><header><strong @click="router.push('/index')">资源分享社区</strong><button @click="router.back()">返回</button></header><main><section><h1>编辑帖子</h1><label>标题<input v-model="form.title" maxlength="100"></label><label>资源链接<input v-model="form.resourceUrl" maxlength="2048"></label><label>正文<textarea v-model="form.content" maxlength="10000" rows="12"></textarea></label><button class="save" :disabled="saving" @click="save">{{saving?'保存中...':'保存修改'}}</button></section></main></div></template>
<style scoped>.page{min-height:100vh;background:#f5f6fa}header{height:60px;background:#fff;border-bottom:1px solid #e8e8e8;display:flex;align-items:center;justify-content:space-between;padding:0 20px}header strong{color:#667eea;cursor:pointer}button{padding:8px 16px;border:1px solid #d9dcf5;background:#fff;color:#667eea;border-radius:6px}main{max-width:860px;margin:auto;padding:24px 20px}section{background:#fff;padding:30px;border-radius:8px}h1{margin-top:0}label{display:block;font-weight:600;margin:18px 0}input,textarea{display:block;width:100%;box-sizing:border-box;margin-top:8px;padding:11px;border:1px solid #e5e5e5;border-radius:6px;font:inherit}.save{background:#667eea;color:#fff;border:0}</style>
